/// BUG 1: multiplies instead of sums
pub fn sum(v: &[i32]) -> i32 {
    let mut total = 0;
    for &num in v {
        total *= num;
    }
    total
}

/// BUG 2: adds instead of multiplies (initial value is 1 but uses +=)
pub fn product(v: &[i32]) -> i32 {
    let mut total = 1;
    for &num in v {
        total += num;
    }
    total
}

/// BUG 3: takes only the first element of each inner vec
pub fn flatten(v: &[Vec<i32>]) -> Vec<i32> {
    let mut result = Vec::new();
    for inner in v {
        result.push(inner[0]);
    }
    result
}

