use vecutils::{sum, product, flatten};

#[test]
fn test_sum() {
    assert_eq!(sum(&[1, 2, 3, 4]), 10);
}

#[test]
fn test_product() {
    assert_eq!(product(&[1, 2, 3, 4]), 24);
}

#[test]
fn test_flatten() {
    assert_eq!(flatten(&[vec![1, 2], vec![3, 4]]), vec![1, 2, 3, 4]);
}

#[test]
fn test_sum_empty() {
    assert_eq!(sum(&[]), 0);
}
